import { useEffect, useState } from "react";

function Attendance() {
  const [students, setStudents] = useState([]);
  const [date, setDate] = useState("");
  const [attendance, setAttendance] = useState({});

  useEffect(() => {
    setStudents(JSON.parse(localStorage.getItem("students")) || []);
  }, []);

  const markAttendance = (studentId, status) => {
    setAttendance({
      ...attendance,
      [studentId]: status
    });
  };

  const saveAttendance = () => {
    if (!date) {
      alert("Please select date");
      return;
    }

    const stored = JSON.parse(localStorage.getItem("attendance")) || {};

    students.forEach(student => {
      if (!stored[student.id]) stored[student.id] = {};
      stored[student.id][date] = attendance[student.id] || "Absent";
    });

    localStorage.setItem("attendance", JSON.stringify(stored));
    alert("Attendance saved for all students");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Attendance (All Students)</h2>

      <input type="date" onChange={e => setDate(e.target.value)} />
      <br /><br />

      {students.map(student => (
        <div key={student.id} style={{ border: "1px solid #ccc", padding: "10px", marginBottom: "5px" }}>
          <b>{student.name}</b>
          <br />
          <button onClick={() => markAttendance(student.id, "Present")}>
            Present
          </button>
          <button onClick={() => markAttendance(student.id, "Absent")}>
            Absent
          </button>
        </div>
      ))}

      <br />
      <button onClick={saveAttendance}>Save Attendance</button>
    </div>
  );
}

export default Attendance;
